using System.Collections.ObjectModel;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class RestoreViewModel:ObservableObject{readonly AgentDashboardClient c;Guid? backupId;string target="",status="";bool ready,running;public string BackupIdText{get=>backupId?.ToString()??"";set{backupId=Guid.TryParse(value,out var x)?x:null;Raise();}}public string Target{get=>target;set=>Set(ref target,value);}public string Status{get=>status;private set=>Set(ref status,value);}public bool Ready{get=>ready;private set{if(Set(ref ready,value))Raise(nameof(CanRestore));}}public bool Running{get=>running;private set{if(Set(ref running,value)){Raise(nameof(CanRestore));Raise(nameof(CanPreflight));}}}public bool CanRestore=>Ready&&!Running;public bool CanPreflight=>!Running;public ObservableCollection<RestoreFileRow> Files{get;}=[];public RestoreViewModel(AgentDashboardClient c)=>this.c=c;public async Task PreflightAsync(){if(Running)return;Ready=false;Files.Clear();if(backupId is null||string.IsNullOrWhiteSpace(Target)){Status="شناسه بکاپ و نام دیتابیس مقصد الزامی است.";return;}Running=true;Status="در حال بررسی اولیه…";try{var x=await c.RestorePreflightAsync(backupId.Value,Target.Trim());if(x is null)return;foreach(var f in x.Files)Files.Add(new(f.LogicalName,f.Type,f.TargetPath));Status=$"بررسی اولیه موفق: {x.SourceDatabaseName} → {x.TargetDatabaseName} | نسخه {x.ProductVersion}";Ready=true;}catch(Exception e){Status=$"خطا: {e.Message}";}finally{Running=false;}}public async Task ExecuteAsync(){if(!CanRestore||backupId is null)return;Running=true;Status="بازیابی در حال انجام است…";try{var x=await c.RestoreAsync(backupId.Value,Target.Trim());Status=x is null?"پاسخی دریافت نشد.":$"بازیابی {x.TargetDatabaseName} در {x.DurationSeconds:0.#} ثانیه تکمیل شد.";Ready=false;}catch(Exception e){Status=$"خطا: {e.Message}";}finally{Running=false;}}}internal sealed record RestoreFileRow(string LogicalName,string Type,string Path);